import React from "react";


export default function PostCard({ post, onImageClick }) {

  // 🔥 detectar si user es objeto o string
  const isUserObject = typeof post.user === "object";

  const nombre = isUserObject ? post.user?.nombre : "";
  const foto = isUserObject
    ? post.user?.foto
    : "https://i.pravatar.cc/50"; // fallback

  return (
    <div className="post-card">

      {/* HEADER */}
      <div className="post-header">
        <img src={foto} alt="user" />
        <h4>{nombre}</h4>
      </div>

      {/* IMAGEN */}
      <img
        src={post.imagen}
        alt="post"
        className="post-img"
        onClick={() => onImageClick(post)}
      />

      {/* DESCRIPCIÓN */}
      <p className="post-desc">{post.descripcion}</p>

      {/* AUDIO */}
      {post.cancion && (
        <audio controls className="post-audio">
          <source src={post.cancion} type="audio/mpeg" />
        </audio>
      )}

    </div>
  );
}
